// FUNCTION: BFME2 0x0033EF8E size=137 name=?xfer@ProjectileStreamUpdate@@MAEXPAVXfer@@@Z evidence=N:ledger
void ProjectileStreamUpdate::xfer(Xfer *xfer)
{
	UpdateModule::xfer(xfer);
	Xfer::Version version(1, 2);
	*xfer == version;
	for (Int i = 0; i < MAX_PROJECTILE_STREAM; ++i)
		XferObjectID(xfer, &m_projectileIDs[i]);
	*xfer == m_nextFreeIndex;
	*xfer == m_firstValidIndex;
	XferObjectID(xfer, &m_owningObject);
	if (version.m_minimum >= 2)
	{
		XferObjectID(xfer, &m_targetObject);
		*xfer == m_targetPosition;
	}
}

// FUNCTION: BFME2 0x0033F033 size=56 name=?cullFrontOfList@ProjectileStreamUpdate@@IAEXXZ evidence=N:ledger
void ProjectileStreamUpdate::cullFrontOfList()
{
	while (m_firstValidIndex != m_nextFreeIndex)
	{
		Int index = m_firstValidIndex;
		if (TheGameLogic->findObjectByID(m_projectileIDs[index]) != NULL)
			break;
		index = (index + 1) % MAX_PROJECTILE_STREAM;
		m_firstValidIndex = index;
	}
}

// FUNCTION: BFME2 0x0033F06B size=37 name=?considerDying@ProjectileStreamUpdate@@IAE_NXZ evidence=N:ledger
Bool ProjectileStreamUpdate::considerDying()
{
	if (m_firstValidIndex == m_nextFreeIndex && m_owningObject != INVALID_ID && TheGameLogic->findObjectByID(m_owningObject) == NULL)
		return TRUE;
	return FALSE;
}

// FUNCTION: BFME2 0x0033F090 size=143 name=?getAllPoints@ProjectileStreamUpdate@@QAEXPAVVector3@@PAH@Z evidence=N:ledger

// FUNCTION: BFME2 0x0033F11F size=45 name=?update@ProjectileStreamUpdate@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger
UpdateSleepTime ProjectileStreamUpdate::update()
{
	cullFrontOfList();
	if (considerDying())
		TheGameLogic->destroyObject(getObject());
	return UPDATE_SLEEP_NONE;
}

